types.prepare:
const choices = Array.isArray(fields.choices) ? fields.choices.slice() : [];
const opts = choices.map((text, idx) => ({
  id: "o" + idx,
  text: String(text || ""),
}));
const correctOpt = opts.find((o) => o.text === String(fields.rule || "")) || opts[0] || { id: "o0", text: String(fields.rule || "") };
const shown = rng.shuffle(opts).map((o) => ({ id: o.id, text: o.text }));

return {
  view: {
    audio: String(fields.audio || ""),
    prompt: String(fields.prompt || ""),
    surah: String(fields.surah || ""),
    reciter: String(fields.reciter || ""),
    chapter: String(fields.chapter || ""),
    mode: String(fields.mode || "rule"),
    blindAudio: !!fields.blindAudio,
    text: String(fields.text || ""),
    focus: String(fields.focus || ""),
    durationSec: Number(fields.durationSec || 0),
    peaks: Array.isArray(fields.peaks) ? fields.peaks : [],
    options: shown,
  },
  key: {
    correctOptionId: correctOpt.id,
    correctRule: String(fields.rule || ""),
    harakat: String(fields.harakat || ""),
    detail: String(fields.detail || ""),
    tajweedHtml: String(fields.tajweedHtml || ""),
    text: String(fields.text || ""),
    focus: String(fields.focus || ""),
    surah: String(fields.surah || ""),
    reciter: String(fields.reciter || ""),
  },
};

grader.code:
const ans = answer && typeof answer === "object" ? answer : {};
const chosen = typeof ans.chosenOptionId === "string" ? ans.chosenOptionId : "";
const isCorrect = !!chosen && chosen === key.correctOptionId;
const revealedText = !!ans.revealedText;

let score = 0.0;
if (isCorrect) {
  score = view.blindAudio && revealedText ? 0.85 : 1.0;
}

return {
  score,
  details: {
    isCorrect,
    chosenOptionId: chosen || null,
    correctOptionId: key.correctOptionId,
    revealedText,
    replays: typeof ans.replays === "number" ? ans.replays : 0,
  },
};

