.tj-blind-veil {
  width: 100%;
  padding: 1rem 0.85rem;
  border-radius: var(--radius);
  border: 1px dashed color-mix(in oklab, var(--tj-gold) 55%, var(--border));
  background: color-mix(in oklab, var(--muted) 45%, transparent);
}

.tj-blind-title {
  font-size: 0.92rem;
  font-weight: 700;
  color: var(--foreground);
  margin-bottom: 0.25rem;
}

.tj-blind-sub {
  font-size: 0.8rem;
  color: var(--muted-foreground);
  line-height: 1.55;
}

/* Dar Al-Ma'rifah inspired Tajweed span colors (shown ONLY on result) */
.tj-ghunnah, .tj-idgham_ghunnah, .tj-ikhafa, .tj-ikhafa_shafawi, .tj-idgham_shafawi, .tj-iqlab {
  color: #0d9488;
}
.tj-qalaqah { color: #2563eb; }
.tj-madda_necessary, .tj-madda_obligatory { color: #dc2626; }
.tj-madda_permissible, .tj-madda_normal { color: #d97706; }
.tj-idgham_wo_ghunnah, .tj-idgham_mutajanisayn, .tj-idgham_mutaqaribayn, .tj-ham_wasl, .tj-slnt, .tj-laam_shamsiyah {
  color: color-mix(in oklab, var(--muted-foreground) 72%, var(--foreground));
}

.tj-legend {
