  flex-wrap: wrap;
  justify-content: center;
  gap: 0.55rem 0.9rem;
  padding-top: 0.45rem;
  border-top: 1px solid color-mix(in oklab, var(--border) 65%, transparent);
  font-size: 0.72rem;
  color: var(--muted-foreground);
}

.tj-leg-item {
  display: inline-flex;
  align-items: center;
  gap: 0.3rem;
}

.tj-leg-item .dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  display: inline-block;
}

.tj-dot-ghunnah { background: #0d9488; }
.tj-dot-qalaqah { background: #2563eb; }
.tj-dot-madd-long { background: #dc2626; }
.tj-dot-madd-short { background: #d97706; }
.tj-dot-silent { background: var(--muted-foreground); }

/* MCQ Options */
.tj-options {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.6rem;
}

@media (max-width: 560px) {
  .tj-options {
    grid-template-columns: 1fr;
  }
}

.tj-option-btn {
  display: flex;
  align-items: center;
  gap: 0.65rem;
  width: 100%;
  padding: 0.78rem 0.9rem;
  text-align: right;
  border-radius: calc(var(--radius) + 2px);
  border: 1px solid var(--border);
  background: var(--card);
  color: var(--foreground);
  font-family: inherit;
  font-size: 0.92rem;
  font-weight: 600;
  cursor: pointer;
