.tj-verdict-meta {
  font-size: 0.78rem;
  color: var(--muted-foreground);
}

.tj-rule-card {
  padding: 0.85rem 1rem;
  border-radius: calc(var(--radius) + 2px);
  border: 1px solid var(--border);
  background: color-mix(in oklab, var(--muted) 45%, var(--card));
