  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
  flex-wrap: wrap;
  margin-bottom: 0.45rem;
}

.tj-rule-title {
  font-size: 0.95rem;
  font-weight: 700;
  color: var(--tj-gold);
}

.tj-harakat-pill {
  font-size: 0.76rem;
  font-weight: 700;
  padding: 0.18rem 0.6rem;
  border-radius: 9999px;
  background: rgba(16, 185, 129, 0.14);
  color: color-mix(in oklab, #10b981 68%, var(--foreground));
  border: 1px solid rgba(16, 185, 129, 0.32);
