template.js:
const { view } = etude;
const startTime = Date.now();
let selectedOptionId = null;
let revealedText = false;
let replays = 0;
let slowMode = false;
let blobUrl = null;
let audioEl = null;

function arabicDigits(value) {
  return String(value == null ? "" : value).replace(/[0-9]/g, (d) => "٠١٢٣٤٥٦٧٨٩"[Number(d)]);
}

function formatTime(sec) {
  const s = Math.max(0, Math.floor(Number(sec) || 0));
  const m = Math.floor(s / 60);
  const rem = s % 60;
  return arabicDigits(`${m}:${rem < 10 ? "0" : ""}${rem}`);
}

const MODE_LABELS = {
  rule: "تحديد الحكم",
  madd: "مقدار المد",
  listen: "تمييز سمعي",
};

const chapterEl = etude.$("#tj-chapter");
const modeEl = etude.$("#tj-mode");
const surahEl = etude.$("#tj-surah");
const reciterEl = etude.$("#tj-reciter");
const promptEl = etude.$("#tj-prompt");
const revealBtn = etude.$("#tj-reveal-verse-btn");
const blindVeilEl = etude.$("#tj-blind-veil");
const verseTextEl = etude.$("#tj-verse-text");
const playBtn = etude.$("#tj-play-btn");
const iconPlay = playBtn.querySelector(".icon-play");
const iconPause = playBtn.querySelector(".icon-pause");
const waveWrap = etude.$("#tj-wave-wrap");
const waveBarsEl = etude.$("#tj-wave-bars");
const timeReadout = etude.$("#tj-time-readout");
const speedBtn = etude.$("#tj-speed-btn");
const replayBtn = etude.$("#tj-replay-btn");
const audioStatus = etude.$("#tj-audio-status");
const optionsEl = etude.$("#tj-options");

chapterEl.textContent = view.chapter || "أحكام التجويد";
modeEl.textContent = MODE_LABELS[view.mode] || "تحديد الحكم";
surahEl.textContent = view.surah || "";
reciterEl.textContent = view.reciter || "";
promptEl.textContent = view.prompt || "";

function renderFocusVerse(targetEl, fullText, focusText) {
  targetEl.textContent = "";
  const full = String(fullText || "");
  const focus = String(focusText || "");
  const idx = focus ? full.indexOf(focus) : -1;
  if (idx < 0) {
    targetEl.textContent = full;
    return;
  }
  if (idx > 0) targetEl.appendChild(document.createTextNode(full.slice(0, idx)));
  const mark = document.createElement("mark");
  mark.className = "tj-focus-mark";
  mark.textContent = focus;
  targetEl.appendChild(mark);
  if (idx + focus.length < full.length) {
    targetEl.appendChild(document.createTextNode(full.slice(idx + focus.length)));
  }
}

function updateVerseVisibility() {
  const showText = !view.blindAudio || revealedText;
  verseTextEl.classList.toggle("hidden", !showText);
  blindVeilEl.classList.toggle("hidden", showText);
  revealBtn.classList.toggle("hidden", !view.blindAudio);
  revealBtn.classList.toggle("is-active", revealedText);
  if (showText) {
    renderFocusVerse(verseTextEl, view.text, view.focus);
  }
}

revealBtn.addEventListener("click", () => {
  if (etude.mode !== "answer") return;
  revealedText = !revealedText;
  updateVerseVisibility();
});

// Waveform bars rendering & interactive scrubbing
const peaks = Array.isArray(view.peaks) && view.peaks.length ? view.peaks : Array(36).fill(35);
waveBarsEl.innerHTML = peaks
  .map((p) => `<span class="tj-bar" style="height:${Math.max(12, Math.min(100, Number(p) || 20))}%"></span>`)
  .join("");
const barEls = Array.from(waveBarsEl.querySelectorAll(".tj-bar"));

function updateProgressUI(curSec, totalSec) {
  const dur = totalSec > 0 ? totalSec : Number(view.durationSec || 0);
  const ratio = dur > 0 ? Math.max(0, Math.min(1, curSec / dur)) : 0;
  const activeCount = Math.round(ratio * barEls.length);
  barEls.forEach((b, i) => b.classList.toggle("is-played", i < activeCount));
  waveWrap.setAttribute("aria-valuenow", String(Math.round(ratio * 100)));
  timeReadout.textContent = `${formatTime(curSec)} / ${formatTime(dur)}`;
}

updateProgressUI(0, Number(view.durationSec || 0));

function setPlayVisual(isPlaying) {
  playBtn.classList.toggle("is-playing", isPlaying);
  iconPlay.classList.toggle("hidden", isPlaying);
  iconPause.classList.toggle("hidden", !isPlaying);
}

async function ensureAudio() {
  if (audioEl) return audioEl;
  const src = String(view.audio || "");
  if (!src) {
    audioStatus.textContent = "لا يوجد ملف صوتي مرفق بهذه البطاقة.";
    audioStatus.classList.remove("hidden");
    return null;
  }
  const el = new Audio();
  el.preload = "auto";
  try {
    const res = await fetch(src);
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    const blob = await res.blob();
    blobUrl = URL.createObjectURL(blob);
    el.src = blobUrl;
  } catch {
    // Fallback to direct media URL if Blob fetch is unavailable
    el.src = src;
  }
  el.preservesPitch = true;
  el.playbackRate = slowMode ? 0.75 : 1.0;

  el.addEventListener("loadedmetadata", () => {
    updateProgressUI(el.currentTime, el.duration);
  });
  el.addEventListener("timeupdate", () => {
    updateProgressUI(el.currentTime, el.duration);
  });
  el.addEventListener("play", () => setPlayVisual(true));
  el.addEventListener("pause", () => setPlayVisual(false));
  el.addEventListener("ended", () => {
    setPlayVisual(false);
    updateProgressUI(el.duration || view.durationSec || 0, el.duration || view.durationSec || 0);
  });
  el.addEventListener("error", () => {
    setPlayVisual(false);
    audioStatus.textContent = "تعذر تشغيل المقطع الصوتي محلياً. تأكد من تنزيل المجموعة الصوتية.";
    audioStatus.classList.remove("hidden");
  });

  audioEl = el;
  return el;
}

async function playAudio(fromStart) {
  const el = await ensureAudio();
  if (!el) return;
  if (fromStart) {
    el.currentTime = 0;
    replays += 1;
  }
  if (el.ended) {
    el.currentTime = 0;
    replays += 1;
  } else if (!fromStart && replays === 0 && el.currentTime < 0.05) {
    replays = 1;
  }
  el.playbackRate = slowMode ? 0.75 : 1.0;
  try {
    await el.play();
  } catch {
    setPlayVisual(false);
  }
}

async function togglePlay() {
  const el = await ensureAudio();
  if (!el) return;
  if (!el.paused && !el.ended) {
    el.pause();
  } else {
    await playAudio(false);
  }
}

