});

waveWrap.addEventListener("click", async (e) => {
  const el = await ensureAudio();
  if (!el) return;
  const rect = waveWrap.getBoundingClientRect();
  const dur = el.duration || Number(view.durationSec || 0);
  if (!dur || rect.width <= 0) return;
  const x = Math.max(0, Math.min(rect.width, e.clientX - rect.left));
  el.currentTime = (x / rect.width) * dur;
  updateProgressUI(el.currentTime, dur);
});

