// Keyboard navigation
window.addEventListener("keydown", (e) => {
  if (e.ctrlKey || e.metaKey || e.altKey) return;
  const k = e.key.toLowerCase();
  if (k === "p") {
    e.preventDefault();
    togglePlay();
    return;
  }
  if (k === "r") {
    e.preventDefault();
    playAudio(true);
    return;
  }
  if (k === "s") {
    e.preventDefault();
    speedBtn.click();
    return;
  }
  if (k === "v" && etude.mode === "answer" && view.blindAudio) {
    e.preventDefault();
    revealBtn.click();
    return;
  }
  if (etude.mode === "answer") {
    const idx = ["1", "2", "3", "4"].indexOf(e.key);
    const btns = etude.$$(".tj-option-btn");
    if (idx >= 0 && idx < btns.length) {
      e.preventDefault();
      chooseAndSubmit(btns[idx].dataset.id);
    }
  }
});

// Safe renderer for sanitized Tajweed markup: ONLY text and <span class="tj-..."> nodes.
function appendSafeTajweed(container, htmlStr, fallbackText) {
  container.textContent = "";
  const raw = String(htmlStr || "").trim();
  if (!raw) {
    container.textContent = fallbackText || "";
    return;
  }
  const tokens = raw.split(/(<\/?span(?:\s+class="tj-[a-z0-9_]+")?>)/g);
  const stack = [container];
  for (const tok of tokens) {
    if (!tok) continue;
    const openMatch = tok.match(/^<span\s+class="(tj-[a-z0-9_]+)">$/);
    if (openMatch) {
      const span = document.createElement("span");
      span.className = openMatch[1];
      stack[stack.length - 1].appendChild(span);
      stack.push(span);
    } else if (tok === "</span>") {
      if (stack.length > 1) stack.pop();
    } else {
      stack[stack.length - 1].appendChild(document.createTextNode(tok));
    }
  }
}

