etude.onResult(({ grade, key, answer }) => {
  const ans = answer || {};
  const isCorrect = grade?.details?.isCorrect ?? (grade?.score != null && grade.score > 0.5);
  const timeSec = typeof ans.timeMs === "number" ? (ans.timeMs / 1000).toFixed(1) : null;

  const coloredEl = etude.$("#tj-verse-colored");
  appendSafeTajweed(coloredEl, key.tajweedHtml, key.text);

  const verdict = etude.$("#tj-verdict");
  const verdictMain = etude.$("#tj-verdict-main");
  const verdictMeta = etude.$("#tj-verdict-meta");
  verdict.classList.add(isCorrect ? "is-correct" : "is-wrong");
  verdictMain.textContent = isCorrect
    ? "✓ أحسنت! إجابة صحيحة وموفّقة"
    : `✕ الإجابة الصحيحة: ${key.correctRule || ""}`;
  if (timeSec) {
    verdictMeta.textContent = `${arabicDigits(timeSec).replace(".", "٫")} ثانية`;
  }

  etude.$("#tj-rule-name").textContent = key.correctRule || "";
  const harakatPill = etude.$("#tj-harakat-pill");
  if (key.harakat) {
    harakatPill.textContent = key.harakat;
    harakatPill.classList.remove("hidden");
  } else {
    harakatPill.classList.add("hidden");
  }
  etude.$("#tj-rule-detail").textContent = key.detail || "";

  let suggested = 3;
  let suggestedLabel = "جيد";
  if (!isCorrect) {
    suggested = 1;
    suggestedLabel = "أعد";
  } else if (ans.revealedText || (typeof ans.timeMs === "number" && ans.timeMs > 10000)) {
    suggested = 2;
    suggestedLabel = "صعب";
  } else if (!ans.revealedText && typeof ans.timeMs === "number" && ans.timeMs < 5500) {
    suggested = 4;
    suggestedLabel = "سهل";
  }
  etude.$("#tj-fsrs-rec").textContent = suggestedLabel;
  etude.$$(".fsrs-btn").forEach((b) => b.classList.toggle("is-suggested", Number(b.dataset.rating) === suggested));
});
